const crypto = require('crypto');
const postText = String($json.post_text ?? '');
const textSha256 = crypto.createHash('sha256').update(postText, 'utf8').digest('hex');
return {
  json: {
    post_text: postText,
    visibility: $json.visibility || 'PUBLIC',
    reshare_parent: $json.reshare_parent || '',
    organization_urn: $json.organization_urn || 'urn:li:organization:72031636',
    publish_target: 'organization_page',
    text_sha256: textSha256
  }
};

return {
  json: {
    ...$json,
    approval_request: {
      decision: 'yes',
      approved_by: 'gideon',
      timestamp: '<ISO-8601 with timezone>',
      text_sha256: $json.text_sha256
    },
    instruction: 'Send this hash to Gideon. He replies by POSTing the Wait resume URL. Any other body stops before LinkedIn.'
  }
};

const draft = $('Hash Draft').item.json;
const parent = String(draft.reshare_parent || '').trim();
const body = {
  author: draft.organization_urn,
  commentary: draft.post_text,
  visibility: draft.visibility || 'PUBLIC',
  distribution: {
    feedDistribution: 'MAIN_FEED',
    targetEntities: [],
    thirdPartyDistributionChannels: []
  },
  lifecycleState: 'PUBLISHED',
  isReshareDisabledByAuthor: false
};
if (parent) {
  body.reshareContext = { parent: parent };
}
return {
  json: {
    posts_body: body,
    organization_urn: draft.organization_urn,
    text_sha256: draft.text_sha256,
    approved_by: $json.approved_by,
    timestamp: $json.timestamp,
    decision: $json.decision
  }
};

const built = $('Build Org Post').item.json;
const headerBag = $json.headers || ($json.response && $json.response.headers) || {};
let postUrn = null;
for (const key of Object.keys(headerBag)) {
  if (String(key).toLowerCase() === 'x-restli-id') {
    postUrn = headerBag[key];
    break;
  }
}
return {
  json: {
    event: 'wf1_published',
    publish_target: 'organization_page',
    organization_urn: built.organization_urn || 'urn:li:organization:72031636',
    post_urn: postUrn,
    text_sha256: built.text_sha256,
    approved_by: built.approved_by,
    timestamp: built.timestamp,
    http_status: $json.statusCode || $json.status || null,
    linkedin_api: true
  }
};

return {
  json: {
    event: 'wf1_not_approved',
    publish_target: 'organization_page',
    linkedin_api: false,
    decision: $json.decision || null,
    approved_by: $json.approved_by || null,
    text_sha256: $json.text_sha256 || null
  }
};
